// ===== Konfiguration: ein Eintrag pro Zoom-Meeting (Teil des Meeting-Themas) =====
// attended = teilgenommen, full = vollständig teilgenommen (> 90 %), notAttended = nicht teilgenommen
const WEBINARS = [
  { match: 'E-Mail Zustellung für Anfänger', attended: '13327964', full: '13440472', notAttended: 'TAG_ID_NICHT_TEILGENOMMEN_ANFAENGER' },
  { match: 'E-Mail Zustellung für Experten', attended: '13327965', full: '13445224', notAttended: 'TAG_ID_NICHT_TEILGENOMMEN_EXPERTEN' },
];
const FULL_ATTENDANCE_RATIO = 0.9;
// ================================================================================

const ev = $('Listen to ending Zoom meetings').first().json.body.payload.object;
const cfg = WEBINARS.find(w => (ev.topic || '').includes(w.match));
if (!cfg) return []; // Meeting is not configured: nothing to do
for (const k of ['attended', 'full', 'notAttended']) {
  if (!/^\d+$/.test(String(cfg[k]))) throw new Error(`Tag-ID "${k}" für "${cfg.match}" ist nicht konfiguriert (Code-Knoten "Aggregate and classify").`);
}

// Actual meeting length in seconds; fallback: scheduled duration (minutes)
const start = new Date(ev.start_time).getTime();
const end = new Date(ev.end_time).getTime();
const actual = end > start ? Math.round((end - start) / 1000) : (Number(ev.duration) || 0) * 60;

// Registrants (empty if the meeting has no registration or the call failed)
const registrants = $('Get meeting registrants').all().flatMap(i => i.json.registrants || []);
const regEmailById = {};
for (const r of registrants) if (r.id && r.email) regEmailById[r.id] = r.email.trim().toLowerCase();

// Participants: drop host/internal users, resolve e-mail via registrant_id if missing, merge rejoins
const byEmail = {};
const attendedRegIds = new Set();
for (const page of $('Get past Zoom meeting participants').all()) {
  for (const p of (page.json.participants || [])) {
    if (p.internal_user) continue;
    const email = ((p.user_email || regEmailById[p.registrant_id] || '') + '').trim().toLowerCase();
    if (p.registrant_id) attendedRegIds.add(p.registrant_id);
    if (!email) continue;
    if (!byEmail[email]) byEmail[email] = { user_email: email, name: (p.name || '').trim(), duration: 0 };
    byEmail[email].duration += Number(p.duration) || 0;
  }
}

const base = { topic: ev.topic || '', meeting_id: String(ev.id || ''), meeting_duration_seconds: actual,
  tag_attended: cfg.attended, tag_full: cfg.full, tag_not_attended: cfg.notAttended };

const out = Object.values(byEmail).map(p => {
  const ratio = actual > 0 ? Math.min(p.duration / actual, 1) : 0;
  return { json: { ...base, ...p, status: 'attended', attendance_ratio: ratio, fully_attended: ratio > FULL_ATTENDANCE_RATIO } };
});

// Registered but never joined -> not attended
const seen = new Set(Object.keys(byEmail));
for (const r of registrants) {
  const email = (r.email || '').trim().toLowerCase();
  if (!email || seen.has(email) || attendedRegIds.has(r.id)) continue;
  seen.add(email);
  const name = [r.first_name, r.last_name].filter(Boolean).join(' ');
  out.push({ json: { ...base, user_email: email, name, duration: 0, status: 'not_attended', attendance_ratio: 0, fully_attended: false } });
}
return out;
